    api = ListAPI(config)
    api.login()

    data = {
        "name": "foo",
        "description": "foo bar",
        "tags": ["t1", "t2"],
        "seeds": ["subject:cheese"],
    }
    result = api.create_list(data)
    assert "key" in result
    assert result['revision'] == 1
