    assert list == {
        "key": result['key'],
        "type": {"key": "/type/list"},
        "revision": 1,
        "latest_revision": 1,
        "name": "foo",
        "description": {"type": "/type/text", "value": "foo bar"},
        "tags": ["t1", "t2"],
        "seeds": ["subject:cheese"],
    }

